import{_ as o}from"./chunks/plus.s75sSGIW.js";import{_ as r,o as a,c as n,a7 as e}from"./chunks/framework.Bn19FVGY.js";const i="/ruidu-docs/images/orbitcontrol/user-guide/annotations-page-main.png",s="/ruidu-docs/images/orbitcontrol/user-guide/annotations-toolbar-draw.png",b=JSON.parse('{"title":"标注","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/annotations.md","filePath":"orbitcontrol/user-guide/annotations.md"}'),l={name:"orbitcontrol/user-guide/annotations.md"};function d(c,t,g,p,h,u){return a(),n("div",null,[...t[0]||(t[0]=[e('<h1 id="标注" tabindex="-1">标注 <a class="header-anchor" href="#标注" aria-label="Permalink to &quot;标注&quot;">​</a></h1><p>「标注」在地图上绘制点、线、多边形，用于标记现场的关键位置和区域（如充电桩、危险区域、巡检点位）。标注归属<strong>地图</strong>：每张地图维护自己的标注，随地图显示。</p><p>标注是设备作业的重要辅助：任务航点可参考标注位置，操作中也可通过标注快速导航。</p><h2 id="进入标注管理" tabindex="-1">进入标注管理 <a class="header-anchor" href="#进入标注管理" aria-label="Permalink to &quot;进入标注管理&quot;">​</a></h2><ol><li>顶部工具栏选择<strong>站点</strong></li><li>选择<strong>地图</strong>（带地球图标的是世界地图类地图）</li></ol><p><img src="'+i+'" alt=""></p><h2 id="绘制标注" tabindex="-1">绘制标注 <a class="header-anchor" href="#绘制标注" aria-label="Permalink to &quot;绘制标注&quot;">​</a></h2><p>地图左侧提供绘制工具：</p><table tabindex="0"><thead><tr><th>工具</th><th>说明</th></tr></thead><tbody><tr><td><strong>绘制点</strong></td><td>在地图上点击放置一个点标注</td></tr><tr><td><strong>绘制线</strong></td><td>依次点击绘制折线，双击（或确认）结束</td></tr><tr><td><strong>绘制多边形</strong></td><td>依次点击绘制多边形，闭合后结束</td></tr></tbody></table><p><img src="'+s+'" alt="" class="w-1/2"></p><p>绘制完成后，弹出标注属性表单：</p><ul><li><strong>名称</strong>：标注名称</li><li><strong>描述</strong>：可选补充说明</li><li><strong>颜色</strong>：标注的显示颜色</li><li><strong>分组</strong>：将标注归入分组，便于批量管理</li></ul><p>保存后标注显示在地图上。点击已有标注可重新编辑或<strong>删除</strong>。</p><h2 id="分组管理" tabindex="-1">分组管理 <a class="header-anchor" href="#分组管理" aria-label="Permalink to &quot;分组管理&quot;">​</a></h2><p>点击工具栏「分组列表」打开右侧分组面板：</p><ul><li>点击 <img src="'+o+'" alt=""> 新建分组（支持嵌套子分组）</li><li>分组用于归类标注，例如「充电设施」「警戒区域」</li></ul><h2 id="在设备控制中使用标注" tabindex="-1">在设备控制中使用标注 <a class="header-anchor" href="#在设备控制中使用标注" aria-label="Permalink to &quot;在设备控制中使用标注&quot;">​</a></h2><p>在 <a href="./live-control.html">设备控制</a> 页面，地图上的标注可以直接用于导航：点击标注，将设备导航至标注位置。</p>',18)])])}const f=r(l,[["render",d]]);export{b as __pageData,f as default};
